  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Measuring the Economy$j$, $j${"readings": [{"title": "Ecclesiastes 3 (King James Version)", "url": "/portal/bible/Ecclesiastes/3"}], "body": "To know whether an economy is healthy, economists measure it. The most common measure is gross domestic product, or GDP, which is the market value of all final goods and services produced within a country in one year. The Bureau of Economic Analysis reports it. Nominal GDP uses current prices, and real GDP adjusts for price changes so that years can be compared fairly. Economic growth means that real GDP rises over time.\n\nThe unemployment rate is the number of people who are jobless and actively looking for work, divided by the labor force, then multiplied by 100. The Bureau of Labor Statistics reports it. Frictional unemployment is short term, as people move between jobs. Structural unemployment happens when skills do not match available jobs. Cyclical unemployment rises when the economy slows.\n\nInflation is a general rise in prices, which lowers the buying power of money. The Consumer Price Index, the CPI, tracks the cost of a typical basket of goods and services. The Federal Reserve aims for inflation of about 2 percent a year.\n\nEconomies move through a business cycle with four phases: expansion, peak, contraction and trough. A long, deep contraction is called a depression. The Great Depression began after the stock market crash of 1929, and unemployment reached about 25 percent. Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven. A wise family and a wise nation prepare in good seasons for lean ones, as Joseph did.\n\nYour task: (1) Define GDP and explain the difference between nominal and real GDP. (2) Tell how the unemployment rate is figured. (3) Name the four phases of the business cycle and describe what inflation does to a dollar.\n\nFlorida standards: SS.912.E.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.E.3", "script": "Welcome back. Listen, a doctor takes your temperature before treating you, and an economist does the same with a nation.\n\nThe main measure is gross domestic product, GDP, the market value of all final goods and services produced inside a country in one year. Nominal GDP uses current prices. Real GDP adjusts for price changes so we can compare years fairly.\n\nNow watch this. The unemployment rate is the number of people who are jobless and looking for work, divided by the labor force, times 100. Frictional unemployment is short term, as people change jobs. Structural unemployment is when skills do not match the jobs. Cyclical unemployment rises when the economy slows.\n\nLook at inflation. It is a general rise in prices, which lowers what a dollar will buy. The Consumer Price Index tracks a typical basket of goods. The Federal Reserve aims for about 2 percent a year.\n\nThe business cycle has four phases: expansion, peak, contraction and trough. The Great Depression began after the crash of 1929, and unemployment reached about 25 percent.\n\nRemember Ecclesiastes 3:1. To every thing there is a season. Prepare in the good seasons for the lean ones, as Joseph did.\n\nYour task is to define GDP, explain the unemployment rate, and name the four phases of the cycle. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Measuring the Economy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Fiscal and Monetary Policy$j$, $j${"readings": [{"title": "Proverbs 27 (King James Version)", "url": "/portal/bible/Proverbs/27"}], "body": "Government tries to keep the economy stable using two sets of tools. Fiscal policy is the use of government spending and taxation by Congress and the President. To fight a slowdown, government can cut taxes or increase spending, which puts more money in circulation. To cool inflation, it can raise taxes or cut spending. The English economist John Maynard Keynes argued during the Great Depression that government spending can lift a weak economy.\n\nEvery year Congress passes a federal budget. When spending is greater than revenue, there is a deficit. When revenue is greater than spending, there is a surplus. The national debt is the total of all past deficits, less any surpluses, that government still owes. Much federal spending is mandatory, such as Social Security and Medicare, some is discretionary, such as defense and education, and some pays interest on the debt.\n\nMonetary policy is the use of the money supply and interest rates by the Federal Reserve. To stimulate the economy, the Fed lowers interest rates so that borrowing is cheaper. To slow inflation, it raises them. Fiscal policy is made by elected officials, while the Fed acts as an independent agency, so it can make hard choices without election pressure.\n\nScripture values wise planning. Proverbs 27:23 says, Be thou diligent to know the state of thy flocks, and look well to thy herds. Proverbs 6:6 says, Go to the ant, thou sluggard; consider her ways, and be wise. A family or a nation that saves and plans wisely stands stronger in hard times.\n\nYour task: (1) Define fiscal policy and monetary policy and tell who makes each. (2) Explain the difference between a deficit and the national debt. (3) Tell what the Fed does to interest rates to slow inflation.\n\nFlorida standards: SS.912.E.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.E.3", "script": "Welcome back. Listen, a nation cannot steer its economy with prayer alone. It needs tools, and there are two sets.\n\nFiscal policy is government spending and taxes, set by Congress and the President. To fight a slowdown, they can cut taxes or spend more. To cool inflation, they can raise taxes or cut spending. John Maynard Keynes argued in the Great Depression that government spending can lift a weak economy.\n\nNow watch this. A deficit is when spending is greater than revenue in a year. A surplus is the reverse. The national debt is the total of past deficits, less surpluses, that government still owes. Do not confuse the two. A deficit is one year. The debt is the whole pile.\n\nMonetary policy is the Federal Reserve using the money supply and interest rates. To stimulate, the Fed lowers rates so borrowing is cheaper. To slow inflation, it raises them. The Fed is independent, so it can make hard choices without election pressure.\n\nRemember Proverbs 27:23, be diligent to know the state of thy flocks. And Proverbs 6:6, go to the ant, consider her ways, and be wise.\n\nYour task is to define fiscal and monetary policy, explain deficit and debt, and tell what the Fed does to slow inflation. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Fiscal and Monetary Policy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Trade and the Global Economy$j$, $j${"readings": [{"title": "1 Kings 10 (King James Version)", "url": "/portal/bible/1Kings/10"}], "body": "Nations trade because no nation has every resource or skill. Exports are goods and services sold to other countries, and imports are those bought from other countries. The idea of comparative advantage explains why trade helps everyone: a country or person should focus on the work that they do at the lowest opportunity cost, and trade for the rest. A lawyer who types faster than her assistant still hires the assistant, because her time is better used on legal work.\n\nGovernments sometimes limit trade. A tariff is a tax on imports. A quota is a limit on the amount of a good that may be imported. An embargo is a ban on trade with a country. Supporters say these protect jobs or national security, but critics say they raise prices for buyers and invite retaliation. Free trade agreements lower such barriers. The United States, Mexico and Canada trade under the United States Mexico Canada Agreement, which took effect in 2020 and replaced the North American Free Trade Agreement. The World Trade Organization, formed in 1995, helps settle trade disputes.\n\nDifferent currencies trade at an exchange rate, the price of one currency in terms of another. When the dollar becomes stronger, imports get cheaper for Americans but exports get more costly for foreign buyers. South Florida is a gateway for trade with the Caribbean and Latin America, and the ports at Fort Lauderdale and Miami move goods in and out of the nation.\n\nTrade is an old practice in Scripture. Proverbs 31:14 says of the virtuous woman, She is like the merchants' ships; she bringeth her food from afar. In 1 Kings 10, Solomon's wisdom and trade brought wealth and visitors from many lands.\n\nYour task: (1) Define export, import and comparative advantage. (2) Describe a tariff and one argument for and against it. (3) Explain what a stronger dollar does to imports and exports.\n\nFlorida standards: SS.912.E.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.E.3", "script": "Welcome back. Listen, the dinner on your table likely came from several countries. That is trade.\n\nExports are goods and services sold to other countries. Imports are those we buy from other countries. Now watch this. Comparative advantage is the reason trade helps everyone. Focus on the work you do at the lowest opportunity cost, and trade for the rest. A lawyer who types faster than her assistant still hires the assistant, because her time is better spent on legal work.\n\nGovernments sometimes limit trade. A tariff is a tax on imports. A quota limits the amount imported. An embargo bans trade with a country. Supporters say these protect jobs and security. Critics say they raise prices and invite retaliation. The United States, Mexico and Canada trade under the USMCA, which took effect in 2020 and replaced NAFTA. The World Trade Organization, formed in 1995, helps settle trade disputes.\n\nLook at the exchange rate. It is the price of one currency in terms of another. A stronger dollar makes imports cheaper for us and our exports costlier for foreigners. South Florida is a gateway to the Caribbean and Latin America.\n\nRemember Proverbs 31:14. She is like the merchants' ships. And 1 Kings 10 shows Solomon's wisdom drawing trade and visitors from many lands.\n\nYour task is to define export, import and comparative advantage, describe a tariff, and explain a stronger dollar. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Trade and the Global Economy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Personal Finance and Stewardship$j$, $j${"readings": [{"title": "Matthew 25 (King James Version)", "url": "/portal/bible/Matthew/25"}], "body": "A steward manages what belongs to another. Deuteronomy 8:18 says, Thou shalt remember the LORD thy God: for it is he that giveth thee power to get wealth. In the parable of the talents in Matthew 25, the master praised the servants who used his goods well, saying in verse 21, Well done, thou good and faithful servant. Good stewardship starts with a plan.\n\nA budget is a plan for your income and spending. List your income, then your needs, wants, giving and savings. One common rule of thumb is to give first, then plan roughly half of income for needs, some for wants, and the rest for saving. Proverbs 3:9 says, Honour the LORD with thy substance, and with the firstfruits of all thine increase, and Malachi 3:10 speaks of bringing the tithes into the storehouse.\n\nSaving builds security. An emergency fund of several months of expenses guards against a job loss or repair. Interest is the price of using money. Simple interest is figured on the starting amount only, so 1,000 dollars at 5 percent for 3 years earns 150 dollars. Compound interest is figured on the amount plus earlier interest, so the same money grows to about 1,157.63 dollars. The rule of 72 says that dividing 72 by the interest rate shows about how many years it takes to double, so at 6 percent it takes about 12 years.\n\nCredit is borrowing with a promise to repay. The annual percentage rate, the APR, is the yearly cost of the loan. A credit score, usually between 300 and 850, shows how reliably you repay. Paying only the minimum on a credit card can leave you in debt for years. Proverbs 22:7 warns that the borrower is servant to the lender. Investing in stocks, bonds or funds may earn more over time, but carries risk, so diversify. Watch for scams that promise quick riches. Proverbs 21:5 says that the thoughts of the diligent tend only to plenty; but of every one that is hasty only to want.\n\nYour task: (1) Build a sample monthly budget with income, giving, needs, wants and savings. (2) Explain the difference between simple and compound interest with the example given. (3) Name two ways to use credit wisely.\n\nFlorida standards: SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.FL", "script": "Welcome back. This is the lesson you will use every week of your life. Listen, a steward manages what belongs to another. Deuteronomy 8:18 says it is the LORD who gives us power to get wealth. In Matthew 25 the master said to the faithful servant, Well done, thou good and faithful servant.\n\nGood stewardship starts with a plan. A budget is a plan for your income and spending. List your income, then giving, needs, wants and savings. Proverbs 3:9 says to honour the LORD with thy substance, and with the firstfruits of all thine increase.\n\nNow watch this. Saving builds security. Keep an emergency fund of several months of expenses. Interest is the price of using money. Simple interest uses the starting amount only, so 1,000 dollars at 5 percent for 3 years earns 150 dollars. Compound interest grows on the interest too, and the same money becomes about 1,157 dollars and 63 cents. The rule of 72 says divide 72 by the rate to find the years to double. At 6 percent, about 12 years.\n\nLook at credit. It is borrowing with a promise to repay. The APR is the yearly cost of the loan. A credit score, usually between 300 and 850, shows how reliably you repay. Paying only the minimum can keep you in debt for years. Proverbs 22:7 says the borrower is servant to the lender.\n\nIf you invest, diversify, and run from anyone promising quick riches. Proverbs 21:5 says haste leads only to want.\n\nYour task is to build a sample budget, explain simple and compound interest, and name two ways to use credit wisely. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Personal Finance and Stewardship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: The National and Personal Economy$j$, $j${"prompt": "Write a report of at least 250 words on the national and personal economy. Use complete sentences and label each part. Matthew 25:21 says, His lord said unto him, Well done, thou good and faithful servant: thou hast been faithful over a few things, I will make thee ruler over many things.\n\nPart 1: Explain GDP, the unemployment rate and inflation, and tell what each shows about the economy.\nPart 2: Describe the four phases of the business cycle and one way government can respond to a slowdown with fiscal policy and with monetary policy.\nPart 3: Explain comparative advantage and one effect of a tariff.\nPart 4: Create a sample monthly budget for a 1,500 dollar income that includes giving, needs, wants and savings, and explain your choices.\nPart 5: Explain compound interest and two ways to avoid trouble with credit.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 15 points. Part 4: 25 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: The National and Personal Economy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Wise Stewards in Hard Times$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells how inflation or a recession could affect a family you know, (2) describes one habit of saving or giving that you will start, (3) explains whether you think trade with other countries helps or hurts American workers, and why, and (4) connects your answer to Proverbs 21:5, which says, The thoughts of the diligent tend only to plenty; but of every one that is hasty only to want. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Is borrowing money for college a wise decision? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Wise Stewards in Hard Times$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Measuring the Economy$j$, $j${"questions": [{"q": "GDP measures:", "options": ["The national debt", "The number of workers", "The value of all final goods and services produced in a country in a year", "Only exports"]}, {"q": "Real GDP differs from nominal GDP because real GDP:", "options": ["Adjusts for changes in prices", "Counts only imports", "Uses no data", "Ignores output"]}, {"q": "Inflation is:", "options": ["A fall in all prices", "A type of tax", "A rise in wages only", "A general rise in prices"]}, {"q": "The four phases of the business cycle are expansion, peak, contraction and:", "options": ["Credit", "Surplus", "Tariff", "Trough"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Measuring the Economy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,3}'::int[], array[$j$GDP is the main measure of national output.$j$,$j$Real GDP removes the effect of inflation.$j$,$j$Inflation lowers the buying power of money.$j$,$j$The low point is called the trough.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Measuring the Economy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Fiscal and Monetary Policy$j$, $j${"questions": [{"q": "Fiscal policy is made by:", "options": ["Congress and the President", "The Supreme Court", "State banks", "The Federal Reserve"]}, {"q": "A budget deficit occurs when:", "options": ["The Fed lowers rates", "Government spending is greater than revenue", "Revenue is greater than spending", "Exports exceed imports"]}, {"q": "To slow inflation, the Federal Reserve would usually:", "options": ["Cut all taxes", "Print more money", "Lower interest rates", "Raise interest rates"]}, {"q": "The national debt is:", "options": ["The total that government owes from past deficits", "One year's deficit", "The Fed's profit", "The trade surplus"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Fiscal and Monetary Policy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0}'::int[], array[$j$It uses government spending and taxation.$j$,$j$A deficit is a one year shortfall.$j$,$j$Higher rates make borrowing cost more and cool spending.$j$,$j$The debt is the accumulated total.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Fiscal and Monetary Policy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Trade and the Global Economy$j$, $j${"questions": [{"q": "A tariff is:", "options": ["A limit on exports only", "A type of loan", "A ban on all trade", "A tax on imported goods"]}, {"q": "Comparative advantage means:", "options": ["Doing the work you do at the lowest opportunity cost", "Having the most resources", "Never trading", "Owning the most land"]}, {"q": "Goods sold to other countries are called:", "options": ["Quotas", "Embargoes", "Exports", "Imports"]}, {"q": "The agreement that replaced NAFTA in 2020 is the:", "options": ["Federal Reserve Act", "Bill of Rights", "United States Mexico Canada Agreement", "Sherman Act"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Trade and the Global Economy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,2}'::int[], array[$j$Tariffs raise the price of imports.$j$,$j$It explains why trade benefits both sides.$j$,$j$Exports leave the country.$j$,$j$USMCA took effect in 2020.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Trade and the Global Economy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Personal Finance and Stewardship$j$, $j${"questions": [{"q": "A budget is:", "options": ["A bank fee", "A tax form", "A plan for income and spending", "A type of loan"]}, {"q": "Simple interest on 1,000 dollars at 5 percent for 3 years is:", "options": ["50 dollars", "1,157 dollars", "500 dollars", "150 dollars"]}, {"q": "Compound interest differs from simple interest because it:", "options": ["Earns interest on earlier interest", "Is a tax", "Applies only to loans", "Is always lower"]}, {"q": "Using the rule of 72, money at 6 percent doubles in about:", "options": ["36 years", "6 years", "72 years", "12 years"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Personal Finance and Stewardship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,3}'::int[], array[$j$A budget lists income, giving, needs, wants and savings.$j$,$j$1,000 times 0.05 times 3 equals 150.$j$,$j$Compounding grows the balance faster.$j$,$j$72 divided by 6 equals 12.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Personal Finance and Stewardship$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: The National and Personal Economy$j$, $j${"questions": [{"q": "The unemployment rate is the share of the labor force that is:", "options": ["Jobless and looking for work", "In school", "Self employed", "Retired"]}, {"q": "The Federal Reserve aims for inflation of about:", "options": ["25 percent", "2 percent a year", "10 percent", "0 percent"]}, {"q": "A national debt is the total of:", "options": ["Past deficits less surpluses still owed", "The trade surplus", "One year's spending", "Bank deposits"]}, {"q": "To stimulate a weak economy, the Fed would usually:", "options": ["Lower interest rates", "Ban imports", "Raise interest rates", "Raise the minimum wage"]}, {"q": "An embargo is:", "options": ["A trade agreement", "A ban on trade with a country", "A limit on quantity", "A tax on imports"]}, {"q": "A strong dollar tends to make imports:", "options": ["Free", "Cheaper for Americans", "More costly for Americans", "Illegal"]}, {"q": "Compound interest earns interest on:", "options": ["The principal only", "Wages", "Taxes", "The principal and earlier interest"]}, {"q": "A credit score is usually a number between:", "options": ["1,000 and 5,000", "0 and 100", "1 and 10", "300 and 850"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: The National and Personal Economy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,0,0,1,1,3,3}'::int[], array[$j$It counts people who want work and cannot find it.$j$,$j$Two percent is the Fed's stated goal.$j$,$j$The debt accumulates over time.$j$,$j$Cheaper loans encourage spending and investment.$j$,$j$It stops trade entirely.$j$,$j$Each dollar buys more foreign currency.$j$,$j$That is why compounding grows faster.$j$,$j$A higher score shows more reliable repayment.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: The National and Personal Economy$j$ on conflict (item_id) do nothing;
